INSERT INTO `syllabus` VALUES (1,'UG History Semester 1','ug-history-sem-1','1',1,'<h2><u>MAJOR COURSE –MJ 1: </u> (Credits: Theory-06)</h2>\r\n<table cellspacing=\"0\">\r\n    <tbody>\r\n        <tr>\r\n            <td>\r\n                <p>Marks: 25 (5 Attd. + 20 SIE: 1Hr) + 75 (ESE: 3Hrs) = 100</p>\r\n            </td>\r\n            <td>\r\n                <p>Pass Marks: Th (SIE + ESE) = 40</p>\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n<p></p>\r\n<p>Instruction to Question Setter for</p>\r\n<p></p>\r\n<p>Semester Internal Examination (SIE 20+5=25 marks):</p>\r\n<p>There will be two group of questions. Question No.1 will be very short answer type in Group A consisting of\r\n    five questions of 1 mark each. Question No.2 will be short answer type of 5 marks. Group B will contain\r\n    descriptive type two questions of ten marks each, out of which any one to answer.</p>\r\n<p>The Semester Internal Examination shall have two components. (a) One Semester Internal Assessment Test (SIA)\r\n    of 20 Marks, (b) Class Attendance Score (CAS) of 5 marks. Conversion of Attendance into score may be as\r\n    follows:</p>\r\n<p>(Attendance Upto 45%, 1mark; 45<Attd.<55, 2 marks; 55<Attd.<65, 3 marks; 65<Attd.<75, 4 marks; 75<Attd, 5 marks)</p>\r\n        <p>End Semester Examination (ESE 75 marks):</p>\r\n        <p>There will be two group of questions. Group A is compulsory which will contain three questions.\r\n            Question No.1 will be very short answer type consisting of five questions of 1 mark each. Question\r\n            No.2 & 3 will be short answer type of 5 marks. Group B will contain descriptive type six questions\r\n            of fifteen marks each, out of which any four are to answer.</p>\r\n        <p>Note: There may be subdivisions in each question asked in Theory Examinations.</p>\r\n        <p></p>\r\n        <h2>IDEA OF BHARATVARSHA</h3>\r\n            <p></p>\r\n            <p>Course Objectives & Learning Outcomes:</p>\r\n            <p></p>\r\n            <p>Theory: 90 Lectures</p>\r\n            <ol>\r\n                <li>\r\n                    <p>Students will acquire knowledge regarding the primitive life and cultural status of the\r\n                        people of Ancient India.</p>\r\n                </li>\r\n                <li>\r\n                    <p>They can gather knowledge about the society, culture, religion and political history of\r\n                        Ancient India.</p>\r\n                </li>\r\n                <li>\r\n                    <p>They will also acquire the knowledge of changing socio-cultural scenarios of India.</p>\r\n                </li>\r\n                <li>\r\n                    <p>The glory of Indian Literature: Ved, Vedanga, Upanishads, Epics, Jain and Buddhist\r\n                        Literature, Smriti, Puranas</p>\r\n                </li>\r\n            </ol>\r\n            <p><strong>Course Content:</strong></p>\r\n            <h3>UNIT- I: Concept of Bharatvarsha:</h3>\r\n            <ol>\r\n                <li>\r\n                    <p>Understanding of Bharatvarsha</p>\r\n                </li>\r\n                <li>\r\n                    <p>Eternity of synonyms Bharat</p>\r\n                </li>\r\n                <li>\r\n                    <p>Indian concept of time and space</p>\r\n                </li>\r\n                <li>\r\n                    <p>The glory of Indian Literature: Ved, Vedanga, Upanishads, Epics, Jain and Buddhist Literature,\r\n                        Smriti,\r\n                        Puranas etc.</p>\r\n                </li>\r\n            </ol>\r\n            <h3>UNIT- II: Indian Knowledge Tradition, Art and Culture</h3>\r\n            <ol>\r\n                <li>\r\n                    <p>Evolution of language and Script: Brahmi, Kharoshthti, Pali, Prakrit, Sanskrit, Tamil. Jain\r\n                        Philosophy:\r\n                        Dravya, Syadvada, Anekantavada, Bondage and Liberation.</p>\r\n                </li>\r\n                <li>\r\n                    <p>Salient features of Indian Art and Culture.</p>\r\n                </li>\r\n                <li>\r\n                    <p>Indian educational system</p>\r\n                </li>\r\n                <li>\r\n                    <p>The Ethics of Indian Valour.</p>\r\n                </li>\r\n            </ol>\r\n            <h3>UNIT- III: Dharma, Philosophy and Vasudhaiva Kutumbakam :</h3>\r\n            <ol>\r\n                <li>\r\n                    <p>Indian perception of Dharma and DarshanVaisheshika Philosophy- Padartha</p>\r\n                </li>\r\n                <li>\r\n                    <p>The concept of Vasudhaiva Kutumbakam : Man, Family, Society and World</p>\r\n                </li>\r\n                <li>\r\n                    <p>Polity and governance</p>\r\n                </li>\r\n                <li>\r\n                    <p>The concept of Janpada and Gram Swarajya </p>\r\n                </li>\r\n            </ol>\r\n            <h3>UNIT- IV: Science, Environment and Medical Science:</h3>\r\n            <ol>\r\n                <li>\r\n                    <p>Science and Technology in Ancient India</p>\r\n                </li>\r\n                <li>\r\n                    <p>Environmental conservation: Indian View</p>\r\n                </li>\r\n                <li>\r\n                    <p>Health consciousness of (Science of Life): Ayurveda, Yoga and Naturopathy</p>\r\n                </li>\r\n                <li>\r\n                    <p>Indian Numeral System and Mathematics</p>\r\n                </li>\r\n            </ol>\r\n            <h3>UNIT- V: Indian Economic Traditions</h3>\r\n            <ol>\r\n                <li>\r\n                    <p>Indian Economic Thoughts</p>\r\n                </li>\r\n                <li>\r\n                    <p>Concept of land, forest and agriculture</p>\r\n                </li>\r\n                <li>\r\n                    <p>Industry, inland trade Commerce</p>\r\n                </li>\r\n                <li>\r\n                    <p>Maritime Trade</p>\r\n                </li>\r\n            </ol>','2024-10-16 04:37:51'),(2,'{ इतिहास } यूजी सेमेस्टर 1','hi-ug-history-1','1',1,'<h2> <u> प्रमुख पाठ्यक्रम -MJ 1: </u> (क्रेडिट: थ्योरी -06) </h2>\r\n<table>\r\n    <tbody>\r\n        <tr>\r\n            <td> <p> मार्क्स: 25 (5 Attd। + 20 Sie: 1hr) + 75 (ese: 3hrs) = 100 </p>\r\n            </td>\r\n            <td> <p> पास के निशान: Th (sie + ese) = 40 </p>\r\n            </td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n<p> </p>\r\n<p> के लिए प्रश्न सेटर के लिए निर्देश </p>\r\n<p> </p>\r\n<p> सेमेस्टर आंतरिक परीक्षा (SIE 20+5 = 25 अंक): </p>\r\n<p> सवालों के दो समूह होंगे। प्रश्न संख्या 1 समूह ए से मिलकर बहुत छोटा उत्तर प्रकार होगा\r\n    प्रत्येक के पांच प्रश्न प्रत्येक को चिह्नित करते हैं। प्रश्न संख्या 2 5 अंकों का संक्षिप्त उत्तर प्रकार होगा।\r\n    समूह बी में शामिल होंगे\r\n    वर्णनात्मक टाइप दो प्रश्न प्रत्येक के दस अंक, जिनमें से कोई भी जवाब देने के लिए। </p>\r\n<p> सेमेस्टर आंतरिक परीक्षा में दो घटक होंगे। (ए) एक सेमेस्टर आंतरिक मूल्यांकन परीक्षण (एसआईए)\r\n    20 अंकों में से, (बी) 5 अंकों के वर्ग उपस्थिति स्कोर (सीएएस)। स्कोर में उपस्थिति का रूपांतरण हो सकता है\r\n    इस प्रकार है: </p>\r\n<p> (45%तक, 1Mark; 45 <attd। <55, 2 अंक; </p>\r\n</p>\r\n<p> अंत सेमेस्टर परीक्षा (ESE 75 अंक): </p>\r\n<p> सवालों के दो समूह होंगे। समूह ए अनिवार्य है जिसमें तीन प्रश्न होंगे।\r\n    प्रश्न संख्या 1 बहुत ही संक्षिप्त उत्तर प्रकार होगा जिसमें प्रत्येक 1 अंक के पांच प्रश्न शामिल हैं। सवाल\r\n    No.2 और 3 5 अंकों का संक्षिप्त उत्तर प्रकार होगा। समूह बी में वर्णनात्मक प्रकार छह प्रश्न होंगे\r\n    प्रत्येक पंद्रह अंक, जिनमें से कोई भी चार जवाब देने के लिए है। </p>\r\n<p> नोट: सिद्धांत परीक्षाओं में पूछे गए प्रत्येक प्रश्न में उपखंड हो सकते हैं। </p>\r\n<p> </p>\r\n<h2> भारतवर्ष का विचार </h3>\r\n    <p> </p>\r\n    <p> पाठ्यक्रम उद्देश्य और सीखने के परिणाम: </p>\r\n    <p> </p>\r\n    <p> सिद्धांत: 90 व्याख्यान </p>\r\n    <ol>\r\n        <li>\r\n            <p> छात्र आदिम जीवन और सांस्कृतिक स्थिति के बारे में ज्ञान प्राप्त करेंगे प्राचीन भारत के लोग। </p>\r\n        </li>\r\n        <li>\r\n            <p> वे समाज, संस्कृति, धर्म और राजनीतिक इतिहास के बारे में ज्ञान इकट्ठा कर सकते हैं प्राचीन भारत। </p>\r\n        </li>\r\n        <li>\r\n            <p> वे भारत के सामाजिक-सांस्कृतिक परिदृश्यों को बदलने का ज्ञान भी प्राप्त करेंगे। </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय साहित्य की महिमा: वेद, वेदंगा, उपनिषद, महाकाव्य, जैन और बौद्ध साहित्य, स्मृति, पुराण </p>\r\n        </li>\r\n    </ol>\r\n    <p> <strong> पाठ्यक्रम सामग्री: </strong> </p>\r\n    <h3> यूनिट- I: भारतवर्ष की अवधारणा: </h3>\r\n    <ol>\r\n        <li>\r\n            <p> भारतवर्ष की समझ </p>\r\n        </li>\r\n        <li>\r\n            <p> समानार्थी भारत की अनंत काल </p>\r\n        </li>\r\n        <li>\r\n            <p> समय और अंतरिक्ष की भारतीय अवधारणा </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय साहित्य की महिमा: वेद, वेदंगा, उपनिषद, महाकाव्य, जैन और बौद्ध साहित्य, स्मृति, पुराण आदि। </p>\r\n        </li>\r\n    </ol>\r\n    <h3> यूनिट- II: भारतीय ज्ञान परंपरा, कला और संस्कृति </h3>\r\n    <ol>\r\n        <li>\r\n            <p> भाषा और स्क्रिप्ट का विकास: ब्रह्मी, खारोशथती, पाली, प्राकृत, संस्कृत, तमिल। जैन दर्शन: द्रव्य, सायदवाड़ा, एनेकांतवाड़ा, बंधन और मुक्ति। </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय कला और संस्कृति की मुख्य विशेषताएं। </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय शैक्षिक प्रणाली </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय वीरता की नैतिकता। </p>\r\n        </li>\r\n    </ol>\r\n    <h3> यूनिट- III: धर्म, दर्शन और वासुधिव कुटुम्बकम: </h3>\r\n    <ol>\r\n        <li>\r\n            <p> धर्म और दर्शनवेशिका दर्शन की भारतीय धारणा- पद्रथा </p>\r\n        </li>\r\n        <li>\r\n            <p> वासुधिव कुटुम्बकम की अवधारणा: आदमी, परिवार, समाज और दुनिया </p>\r\n        </li>\r\n        <li>\r\n            <p> राजनीति और शासन </p>\r\n        </li>\r\n        <li>\r\n            <p> जनता और ग्राम स्वराज्य की अवधारणा </p>\r\n        </li>\r\n    </ol>\r\n    <h3> यूनिट- IV: विज्ञान, पर्यावरण और चिकित्सा विज्ञान: </h3>\r\n    <ol>\r\n        <li>\r\n            <p> प्राचीन भारत में विज्ञान और प्रौद्योगिकी </p>\r\n        </li>\r\n        <li>\r\n            <p> पर्यावरण संरक्षण: भारतीय दृश्य </p>\r\n        </li>\r\n        <li>\r\n            <p> स्वास्थ्य चेतना (जीवन का विज्ञान): आयुर्वेद, योग और प्राकृतिक चिकित्सा </p>\r\n        </li>\r\n        <li>\r\n            <p> भारतीय अंक प्रणाली और गणित </p>\r\n        </li>\r\n    </ol>\r\n    <h3> यूनिट- V: भारतीय आर्थिक परंपराएं </h3>\r\n    <ol>\r\n        <li>\r\n            <p> भारतीय आर्थिक विचार </p>\r\n        </li>\r\n        <li>\r\n            <p> भूमि, वन और कृषि की अवधारणा </p>\r\n        </li>\r\n        <li>\r\n            <p> उद्योग, अंतर्देशीय व्यापार वाणिज्य </p>\r\n        </li>\r\n        <li>\r\n            <p> समुद्री व्यापार </p>\r\n        </li>\r\n    </ol>','2024-10-16 04:37:51'),(3,'UG History Semester 2','ug-history-sem-2','1',1,'v','2025-01-26 14:42:27'),(4,'UG History Semester 3','ug-history-semester-3','1',1,'UG History Semester 3','2025-01-26 14:47:32'),(5,'UG History Semester 4','ug-history-semester-4','1',1,'UG History Semester 4','2025-01-26 14:52:37'),(6,'UG History Semester 5','ug-history-semester-5','1',1,'UG History Semester 5','2025-01-26 14:52:37'),(7,'UG History Semester 6','ug-history-semester-6','1',1,'UG History Semester 6','2025-01-26 14:52:37'),(8,'PG History Semester 1','pg-history-semester-1','1',1,'PG History Semester 1','2025-01-26 14:52:37'),(9,'PG History Semester 2','pg-history-semester-2','2',1,'PG History Semester 2','2025-01-26 14:52:37'),(10,'PG History Semester 3','pg-history-semester-3','1',1,'<h2>CORE COURSE [CCHIS207]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>Marks: 30 (MSE: 20Th. 1Hr + 5Attd. + 5Assign.) + 70 (ESE: 3Hrs)=100</strong></p>\r\n    <p>Pass Marks (MSE:17 + ESE:28)=45</strong></p>\r\n</div>\r\n<h2>Instruction to Question Setter:</h2>\r\n<p><i>Mid Semester Examination (MSE):</i></p>\r\n<p>There will be two groups of questions in written examinations of 20 marks. <strong>Group A is compolsory</strong> and will contain five questions of <strong>very short answer type</strong>  consisting of 1 mark each <strong>Group B will contain descriptive type five</strong> questions of five marks each, out of which any three are to be answered.</p>\r\n<p><i>End Semester Examination (ESE):</i></p>\r\n<p>There will be two groups of questions. Group A is compolsory and will contain two questions. Question No.1 will be very short answer type consisting of four questions of 1 mark each. Question No.2 will be short answer type of 5x2=10 marks. Group B will contain descriptive type seven questions of fourteen marks each, out of which any four are to be answered.</p>\r\n<p>Note :</strong> There may be subdivisions in each question asked in Theory Examinations The Mid Semester Examination shall have three components. (a) Two Semester Internal Assessment Test (SIA) of 20 Marks each, (b) Class Attendance Score (CAS) of 5 marks and (c) Class Performance Score (CPS) of 5 marks. \"<strong>Best of Two</strong>\" shall be applicable for computation of marks for SIA.</p>\r\n<p><i>(Attendance Upto 75%, 1mark; 75 < Attd.< 80, 2 marks; 80< Attd.< 85, 3 marks; 85< Attd.< 90, 4 marks; 90< Attd, 5 marks).</i></p>\r\n\r\n\r\n<h2>SOCIO-RELIGIOUS MOVEMENTS IN INDIA</h2>\r\n<p>Theory: 60 Lectures; Tutorial:15 Hrs</strong></p>\r\n<h3>Unit I : Social life of India from earliest days to Gupta period.</h3>\r\n<ol>\r\n    <li><p>Harappan Society</p></li>\r\n    <li><p>Vedic Society</p></li>\r\n    <li><p>Mauryan Society</p></li>\r\n    <li><p>Gupta Society</p></li>\r\n</ol>\r\n<h3>Unit II : Religious movement from earliest days to Gupta period.</h3>\r\n<ol>\r\n    <li><p>Shaivism</p></li>\r\n    <li><p>Jainism</p></li>\r\n    <li><p>Buddhism</p></li>\r\n    <li><p>Bhaghavatism (Vaisnavism)</p></li>\r\n</ol>\r\n<h3>Unit III : Medieval India and Indian Socio-Religious life in Soltunate Period.</h3>\r\n<ol>\r\n    <li><p>Social Structure of Soltunate Period</p></li>\r\n    <li><p>Bhakti Movement</p></li>\r\n    <li><p>Sufism</p></li>\r\n    <li><p>Nath Colt</p></li>\r\n</ol>\r\n<h3>Unit IV : Medieval India and Indian Socio-Religious life in Mughal India.</h3>\r\n<ol>\r\n    <li><p>Social Structure of Mughal Period</p></li>\r\n    <li><p>Bhakti Movement</p></li>\r\n    <li><p>Din-i-Ilahi</p></li>\r\n    <li><p>Sikhism</p></li>\r\n</ol>\r\n<h3>Unit V </strong>: Socio-Religious Movements in Modern India</h3>\r\n<ol>\r\n    <li><p>Brahmo Samaj</p></li>\r\n    <li><p>Arya Samaj</p></li>\r\n    <li><p>Theosophical Society</p></li>\r\n    <li><p>Muslim Reform Movement</p></li>\r\n</ol>\r\n\r\n<div class=\"endpage\"></div>\r\n\r\n<h2>CORE COURSE [CCHIS308]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>Marks: 30 (MSE: 20Th. 1Hr + 5Attd. + 5Assign.) + 70 (ESE: 3Hrs)=100</p>\r\n    <p>Pass Marks (MSE:17 + ESE:28)=45</p>\r\n</div>\r\n<h2>CONTEMPORARY INDIA (1947-2000)</h2>\r\n<p>Theory: 60 Lectures; Tutorial:15 Hrs</strong></p>\r\n\r\n\r\n<h3>Unit I : Nehru Era.</h3>\r\n<ol>\r\n    <li><p>Making of Constitution</p></li>\r\n    <li><p>Challenges before Indian States and National Integration</p></li>\r\n    <li><p>Foreign policy of India under Nehru</p></li>\r\n    <li><p>Non-Alignment - under Nehru</p></li>\r\n</ol>\r\n<h3>Unit II : Breakdown of Congress System</h3>\r\n<ol>\r\n    <li><p>L. B. Shastri and Indo-Pak relations</p></li>\r\n    <li><p>New Political Alignment</p></li>\r\n    <li><p>Indira Gandhi – War of 1971</p></li>\r\n    <li><p>Foreign Policy of Indira Gandhi</p></li>\r\n</ol>\r\n<h3>Unit III : Dimensions of Indian Democracy</h3>\r\n<ol>\r\n    <li><p>Emergency</p></li>\r\n    <li><p>Movement of Jai Prakash Narayan</p></li>\r\n    <li><p>Janta Party Role</p></li>\r\n    <li><p>Foreign Policy of Atal Bihari Vajpayee (1998-2004)</p></li>\r\n</ol>\r\n<h3>Unit IV : Changing Trends</h3>\r\n<ol>\r\n    <li><p>Rajiv Gandhi and New Economic Policy</p></li>\r\n    <li><p>Emergence of Hindu Nation</p></li>\r\n    <li><p>Mandal Politics</p></li>\r\n    <li><p>Urbanization in Modern India</p></li>\r\n</ol>\r\n<h3>Unit V : Economic Development</h3>\r\n<ol>\r\n    <li><p>Land Reforms - Abolition of Zamindari System, Land Ceiling</p></li>\r\n    <li><p>Nationalization</p></li>\r\n    <li><p>Green Revolution</p></li>\r\n    <li><p>Economic Reform Movement (1991)</p></li>\r\n</ol>\r\n<div class=\"endpage\"></div>\r\n<h2>CORE COURSE [CCHIS309]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>Marks: 30 (MSE: 20Th. 1Hr + 5Attd. + 5Assign.) + 70 (ESE: 3Hrs)=100</p>\r\n    <p>Pass Marks (MSE:17 + ESE:28)=45</p>\r\n</div>\r\n<h2>POLITICAL THOUGHT</h2>\r\n<p>Theory: 60 Lectures; Tutorial:15 Hrs</strong></p>\r\n<h3>Unit I  : Ancient Thinkers</h3>\r\n<ol>\r\n    <li><p>Plato’s contribution: An estimate</p></li>\r\n    <li><p>Aristotle’s Theory of the State</p></li>\r\n    <li><p>Kautilya - Saptanga Theory</p></li>\r\n    <li><p>Kautilya - Mandala Theory</p></li>\r\n</ol>\r\n<h3>Unit II : Concept of Social Contracts</h3>\r\n<ol>\r\n    <li><p>Hobbes - Nature of State and Sovereignty</p></li>\r\n    <li><p>Locke - Natural Rights</p></li>\r\n    <li><p>Locke - Theory of Government</p></li>\r\n    <li><p>Rousseau - Social Contract theory</p></li>\r\n</ol>\r\n<h3>Unit III  : Medieval Political Philosophy</h3>\r\n<ol>\r\n    <li><p>St. Thomas Aquinos</p></li>\r\n    <li><p>Machiavelli-Statecraft in Prince</p></li>\r\n    <li><p>Political Philosophy of Machiavelli</p></li>\r\n    <li><p>Monstesquieu-Separation of Power</p></li>\r\n</ol>\r\n<h3>Unit IV : Modern Political Philosophy</h3>\r\n<ol>\r\n    <li><p>Bentham’s Utilitarianism</p></li>\r\n    <li><p>J. S. Mill’s on Liberty</p></li>\r\n    <li><p>Fredrick Hegel’s views on State</p></li>\r\n    <li><p>Marx - Dialectical Materialism\r\n    </p></li>\r\n</ol>\r\n<h3>Unit V : Modern Indian Philosophy</h3>\r\n<ol>\r\n    <li><p>Mahatma Gandhi - Satyagrah</p></li>\r\n    <li><p>Mahatma Gandhi - Ahimsa</p></li>\r\n    <li><p>Savarkar and Hindutwa</p></li>\r\n    <li><p>Ambedkar and its ideas</p></li>\r\n</ol>\r\n<div class=\"endpage\"></div>','2025-01-26 14:52:37'),(11,'PG History Semester 4','pg-history-semester-4','1',1,'PG History Semester 4','2025-01-26 14:52:37'),(13,'पीजी इतिहास सेमेस्टर 3','hi-pg-history-semester-3','1',1,'<h2>कोर कोर्स [CCHIS307]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>अंक: 30 (MSE: 20थ. 1 घंटा + 5 उपस्थिति + 5 असाइन.) + 70 (ESE: 3 घंटा) = 100</p>\r\n    <p>पास अंक (MSE:17 + ESE:28) = 45</p>\r\n</div>\r\n<h2>प्रश्न सेट करने के लिए निर्देश:</h2>\r\n<p><i>मध्यम सेमेस्टर परीक्षा (MSE):</i></p>\r\n<p>लिखित परीक्षा में दो समूहों के प्रश्न होंगे जिनकी कुल संख्या 20 अंक होगी। <strong>समूह A अनिवार्य है</strong> और इसमें पांच प्रश्न होंगे जो <strong>बहुत छोटे उत्तर प्रकार</strong> होंगे, जिनमें प्रत्येक में 1 अंक होगा। <strong>समूह B में विस्तृत प्रकार के पांच प्रश्न होंगे</strong>, जिनमें से कोई तीन उत्तर देने होंगे।</p>\r\n<p><i>अंतिम सेमेस्टर परीक्षा (ESE):</i></p>\r\n<p>दो समूहों में प्रश्न होंगे। समूह A अनिवार्य है और इसमें दो प्रश्न होंगे। प्रश्न संख्या 1 बहुत छोटे उत्तर प्रकार का होगा, जिसमें चार प्रश्न 1 अंक के होंगे। प्रश्न संख्या 2 छोटे उत्तर प्रकार का होगा, 5x2 = 10 अंक का। समूह B में सात विस्तृत प्रकार के प्रश्न होंगे, जिनमें से कोई चार उत्तर देने होंगे।</p>\r\n<p>नोट :</strong> प्रत्येक प्रश्न में उपविभाग हो सकते हैं जो थेयोरी परीक्षा में पूछे जा सकते हैं। मध्य सेमेस्टर परीक्षा में तीन घटक होंगे। (a) दो सेमेस्टर आंतरिक मूल्यांकन परीक्षा (SIA) प्रत्येक के 20 अंक, (b) कक्षा उपस्थिति अंक (CAS) 5 अंक और (c) कक्षा प्रदर्शन अंक (CPS) 5 अंक। \"<strong>दो में से सबसे अच्छे</strong>\" अंक की गणना SIA के लिए की जाएगी।</p>\r\n<p><i>(उपस्थिति 75% तक, 1 अंक; 75 < उपस्थिति < 80, 2 अंक; 80 < उपस्थिति < 85, 3 अंक; 85 < उपस्थिति < 90, 4 अंक; 90 < उपस्थिति, 5 अंक)।</i></p>\r\n\r\n<h2>भारत में सामाजिक-धार्मिक आंदोलन</h2>\r\n<p>सिद्धांत: 60 व्याख्यान; ट्यूटोरियल: 15 घंटे</p>\r\n<h3>यूनिट I : भारत का सामाजिक जीवन प्रारंभिक दिनों से गुप्त काल तक।</h3>\r\n<ol>\r\n    <li><p>हड़प्पा समाज</p></li>\r\n    <li><p>वैदिक समाज</p></li>\r\n    <li><p>मौर्य समाज</p></li>\r\n    <li><p>गुप्त समाज</p></li>\r\n</ol>\r\n<h3>यूनिट II : धार्मिक आंदोलन प्रारंभिक दिनों से गुप्त काल तक।</h3>\r\n<ol>\r\n    <li><p>शैववाद</p></li>\r\n    <li><p>जैन धर्म</p></li>\r\n    <li><p>बौद्ध धर्म</p></li>\r\n    <li><p>भागवतवाद (वैष्णव धर्म)</p></li>\r\n</ol>\r\n<h3>यूनिट III : मध्यकालीन भारत और सुलतान काल में भारतीय सामाजिक-धार्मिक जीवन।</h3>\r\n<ol>\r\n    <li><p>सुलतान काल की सामाजिक संरचना</p></li>\r\n    <li><p>भक्ति आंदोलन</p></li>\r\n    <li><p>सूफीवाद</p></li>\r\n    <li><p>नाथ पंथ</p></li>\r\n</ol>\r\n<h3>यूनिट IV : मध्यकालीन भारत और मुग़ल भारत में भारतीय सामाजिक-धार्मिक जीवन।</h3>\r\n<ol>\r\n    <li><p>मुग़ल काल की सामाजिक संरचना</p></li>\r\n    <li><p>भक्ति आंदोलन</p></li>\r\n    <li><p>दीन-ए-इलाही</p></li>\r\n    <li><p>सिख धर्म</p></li>\r\n</ol>\r\n<h3>यूनिट V : आधुनिक भारत में सामाजिक-धार्मिक आंदोलन</h3>\r\n<ol>\r\n    <li><p>ब्रह्म समाजा</p></li>\r\n    <li><p>आर्य समाज</p></li>\r\n    <li><p>थेओसॉफिकल सोसाइटी</p></li>\r\n    <li><p>मुस्लिम सुधार आंदोलन</p></li>\r\n</ol>\r\n\r\n<div class=\"endpage\"></div>\r\n\r\n<h2>कोर कोर्स [CCHIS308]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>अंक: 30 (MSE: 20थ. 1 घंटा + 5 उपस्थिति + 5 असाइन.) + 70 (ESE: 3 घंटा) = 100</p>\r\n    <p>पास अंक (MSE:17 + ESE:28) = 45</p>\r\n</div>\r\n<h2>समकालीन भारत (1947-2000)</h2>\r\n<p>सिद्धांत: 60 व्याख्यान; ट्यूटोरियल: 15 घंटे</p>\r\n\r\n<h3>यूनिट I : नेहरू काल</h3>\r\n<ol>\r\n    <li><p>संविधान का निर्माण</p></li>\r\n    <li><p>भारतीय राज्यों के सामने चुनौतियाँ और राष्ट्रीय एकता</p></li>\r\n    <li><p>नेहरू के तहत भारत की विदेश नीति</p></li>\r\n    <li><p>गैर-निर्णय - नेहरू के तहत</p></li>\r\n</ol>\r\n<h3>यूनिट II : कांग्रेस प्रणाली का टूटना</h3>\r\n<ol>\r\n    <li><p>L. B. शास्त्री और भारत-पाकिस्तान संबंध</p></li>\r\n    <li><p>नई राजनीतिक व्यवस्था</p></li>\r\n    <li><p>इंदिरा गांधी – 1971 का युद्ध</p></li>\r\n    <li><p>इंदिरा गांधी की विदेश नीति</p></li>\r\n</ol>\r\n<h3>यूनिट III : भारतीय लोकतंत्र के आयाम</h3>\r\n<ol>\r\n    <li><p>आपातकाल</p></li>\r\n    <li><p>जय प्रकाश नारायण का आंदोलन</p></li>\r\n    <li><p>जनता पार्टी की भूमिका</p></li>\r\n    <li><p>अटल बिहारी वाजपेयी की विदेश नीति (1998-2004)</p></li>\r\n</ol>\r\n<h3>यूनिट IV : बदलते रुझान</h3>\r\n<ol>\r\n    <li><p>राजीव गांधी और नई आर्थिक नीति</p></li>\r\n    <li><p>हिंदू राष्ट्र का उदय</p></li>\r\n    <li><p>मंडल राजनीति</p></li>\r\n    <li><p>आधुनिक भारत में शहरीकरण</p></li>\r\n</ol>\r\n<h3>यूनिट V : आर्थिक विकास</h3>\r\n<ol>\r\n    <li><p>भूमि सुधार - ज़मींदारी उन्मूलन, भूमि सीमा</p></li>\r\n    <li><p>राष्ट्रीयकरण</p></li>\r\n    <li><p>हरित क्रांति</p></li>\r\n    <li><p>आर्थिक सुधार आंदोलन (1991)</p></li>\r\n</ol>\r\n<div class=\"endpage\"></div>\r\n\r\n<h2>कोर कोर्स [CCHIS309]</h2>\r\n<div class=\"flexWrap\">\r\n    <p>अंक: 30 (MSE: 20थ. 1 घंटा + 5 उपस्थिति + 5 असाइन.) + 70 (ESE: 3 घंटा) = 100</p>\r\n    <p>पास अंक (MSE:17 + ESE:28) = 45</p>\r\n</div>\r\n<h2>राजनीतिक विचार</h2>\r\n<p>सिद्धांत: 60 व्याख्यान; ट्यूटोरियल: 15 घंटे</p>\r\n\r\n<h3>यूनिट I : प्राचीन विचारक</h3>\r\n<ol>\r\n    <li><p>प्लेटो का योगदान: एक आकलन</p></li>\r\n    <li><p>अरस्तू का राज्य सिद्धांत</p></li>\r\n    <li><p>कौटिल्य - सप्तांग सिद्धांत</p></li>\r\n    <li><p>कौटिल्य - मंडल सिद्धांत</p></li>\r\n</ol>\r\n<h3>यूनिट II : सामाजिक अनुबंध का सिद्धांत</h3>\r\n<ol>\r\n    <li><p>हॉब्स - राज्य और संप्रभुता की प्रकृति</p></li>\r\n    <li><p>लॉक - प्राकृतिक अधिकार</p></li>\r\n    <li><p>लॉक - सरकार का सिद्धांत</p></li>\r\n    <li><p>रूसो - सामाजिक अनुबंध सिद्धांत</p></li>\r\n</ol>\r\n<h3>यूनिट III : मध्यकालीन राजनीतिक दर्शन</h3>\r\n<ol>\r\n    <li><p>संत थॉमस एक्विनास</p></li>\r\n    <li><p>मैकियावेली - प्रिंस में राज्यcraft</p></li>\r\n    <li><p>मैकियावेली का राजनीतिक दर्शन</p></li>\r\n    <li><p>मोंटेस्क्यू - शक्ति का पृथक्करण</p></li>\r\n</ol>\r\n<h3>यूनिट IV : आधुनिक राजनीतिक दर्शन</h3>\r\n<ol>\r\n    <li><p>बेंथम का उपयोगितावाद</p></li>\r\n    <li><p>J.S. मिल का \"ऑन लिबर्टी\"</p></li>\r\n    <li><p>फ्रेडरिक हेगेल का राज्य पर विचार</p></li>\r\n    <li><p>मार्क्स - वैचारिक भौतिकवाद</p></li>\r\n</ol>\r\n<h3>यूनिट V : आधुनिक भारतीय दर्शन</h3>\r\n<ol>\r\n    <li><p>महात्मा गांधी - सत्याग्रह</p></li>\r\n    <li><p>महात्मा गांधी - अहिंसा</p></li>\r\n    <li><p>सावरकर और हिंदुत्व</p></li>\r\n    <li><p>अंबेडकर और उनके विचार</p></li>\r\n</ol>\r\n<div class=\"endpage\"></div>\r\n','2025-03-24 00:11:22');
